14	export function tpBuildSite(bridge: ThuanPhuocBridge) {
15	  const z0 = TP.z, Y = CONFIG.landY, B = CONFIG.bankX, rnd = rng(1965);
16	  const wN = -3250 - z0, eN = -3700 - z0;                 // bờ biển phía Bắc (Tây / Đông), cục bộ
17	  const wS = -2600 - z0, eS = -2300 - z0;                 // mép đất hiện có
18	  const box = (x0: number, x1: number, za: number, zb: number, y0: number, y1: number) => { const g = new THREE.BoxGeometry(x1 - x0, y1 - y0, zb - za); g.translate((x0 + x1) / 2, (y0 + y1) / 2, (za + zb) / 2); return g; };
19	  bridge.group.add(shadowed(new THREE.Mesh(mergeGeometries([
20	    box(-14000, -B, wN, wS, -6, Y), box(B, 1480, eN, eS, -6, Y)
21	  ]), MAT.land), false, true));
22	  bridge.group.add(shadowed(new THREE.Mesh(box(1480, 1600, eN, eS, -6, 1.2), MAT.sand), false, true));
23	  bridge.group.add(shadowed(new THREE.Mesh(mergeGeometries([
24	    box(-B - 2, -B, wN, wS, -3, Y + 0.5), box(B, B + 2, eN, eS, -3, Y + 0.5),
25	    box(-3200, -B, wN - 2, wN, -3, Y + 0.5), box(B, 1480, eN - 2, eN, -3, Y + 0.5)
26	  ]), MAT.stone), false, true));
27	  bridge.group.add(shadowed(new THREE.Mesh(mergeGeometries([
28	    box(-B - 26, -B - 2, wN, wS, Y, Y + 0.05), box(B + 2, B + 26, eN, eS, Y, Y + 0.05)
29	  ]), MAT.paver), false, true));
30	  // đường ven sông nối dài: Như Nguyệt / Bạch Đằng (Tây), Trần Hưng Đạo (Đông)
31	  const roads = [], med = [];
32	  for (const [xc, za, zb] of [[-299, wN + 40, wS], [299, eN + 40, eS]]) {
33	    for (const s of [-1, 1]) {
34	      const g = zPlane(zb - za, 9, xc + s * 6, Y + 0.02, (za + zb) / 2, s < 0);
35	      const p = g.attributes.position, uv = g.attributes.uv;
36	      for (let i = 0; i < uv.count; i++) uv.setX(i, p.getZ(i) / 12);
37	      roads.push(g);
38	    }
39	    med.push(box(xc - 1.5, xc + 1.5, za, zb, Y, Y + 0.3));
40	  }
41	  const sr = shadowed(new THREE.Mesh(mergeGeometries(roads), MAT.road2), false, true);
42	  const sm = shadowed(new THREE.Mesh(mergeGeometries(med), MAT.grass), false, true);
43	  bridge.group.add(sr, sm); bridge.noReflect.push(sr, sm);
44	  // nhà thấp tầng / trung tầng quanh hai đầu cầu (ngoài hành lang cầu)
45	  const list: [number, number, number, number, number][] = [];
46	  const place = (xa: number, xb: number, za: number, zb: number, hMax: number) => {
47	    for (let x = xa; x < xb; x += 34) for (let z = za; z < zb; z += 34) {
48	      if (Math.abs(z) < 42 || rnd() < 0.3) continue;
49	      list.push([x + (rnd() - 0.5) * 8, z + (rnd() - 0.5) * 8, 12 + rnd() * 14, 12 + rnd() * 14, 8 + rnd() * hMax]);
50	    }
51	  };
52	  place(-1700, -360, wN + 60, wS - 20, 40);
53	  place(360, 1380, -400, eS - 20, 28);
54	  const bm = new THREE.InstancedMesh(new THREE.BoxGeometry(1, 1, 1).translate(0, 0.5, 0), bridge.mats.building, list.length);
55	  const m = new THREE.Matrix4(), q = new THREE.Quaternion(), v = new THREE.Vector3(), sc = new THREE.Vector3(), col = new THREE.Color();
56	  const palette = [0xf3f0e7, 0xeae2cf, 0xdadcdc, 0xcfe0e7, 0xe6dccb, 0xf6f6f2];
57	  list.forEach(([x, z, w, d, h], i) => {
58	    bm.setMatrixAt(i, m.compose(v.set(x, Y, z), q, sc.set(w, h, d)));
59	    bm.setColorAt(i, col.setHex(palette[Math.floor(rnd() * palette.length)]));
60	  });
61	  bm.castShadow = bm.receiveShadow = true;
62	  bridge.group.add(bm); bridge.noReflect.push(bm);
63	  // cây dọc kè mới
64	  const trees: [number, number][] = [];
65	  for (const [xs, za, zb] of [[-1, wN + 10, wS], [1, eN + 10, eS]]) for (let z = za; z < zb; z += 15) {
66	    if (Math.abs(z) < 26) continue;
67	    trees.push([xs * (B + 9 + rnd() * 12), z]);
68	  }
69	  // cây bóng mát (G1), cùng quy ước ma trận với environment/trees.ts: thân (r, h + 0,6r, r), tán giữ tâm / tỉ lệ cũ, xoay theo chỉ số
70	  const trunks = new THREE.InstancedMesh(trShadeTrunkGeo(), MAT.trunk, trees.length);
71	  const crownLod = trShadeCrownLodGeo();   // hình học gộp [đầy đủ | thưa] cho lượt bóng / phản chiếu (src/core/passLod.ts)
72	  const crowns = new THREE.InstancedMesh(crownLod.geo, MAT.leaf, trees.length);
73	  trees.forEach(([x, z], i) => {
74	    const h = 3 + rnd() * 2.5, r = 2.4 + rnd() * 1.8;
75	    q.setFromAxisAngle(THREE.Object3D.DEFAULT_UP, trYaw(i, CONFIG.trees.shade.seed + 3));
76	    trunks.setMatrixAt(i, m.compose(v.set(x, Y, z), q, sc.set(r, h + r * 0.6, r)));
77	    crowns.setMatrixAt(i, m.compose(v.set(x, Y + h + r * 0.6, z), q, sc.set(r, r * 0.85, r)));
78	    crowns.setColorAt(i, col.setHSL(0.27 + rnd() * 0.06, 0.45, 0.35 + rnd() * 0.12));
79	  });
80	  passLodAdd(crowns, crownLod.fullCount, crownLod.lodCount);
81	  trunks.name = 'tp-trees-trunk'; crowns.name = 'tp-trees-crown';
82	  trunks.castShadow = crowns.castShadow = true;
83	  bridge.details.add(trunks, crowns);
84	}
